// @FIGURE_CODE_BEGIN
var NSVG = 'http://www.w3.org/2000/svg';
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 680, FH = 880;
figDraw.viewbox(0, 0, FW, FH).attr('preserveAspectRatio', 'xMidYMid meet');

var O = { x: 215, y: 390 }, R = 208;
var C_CIRC = '#2BA6DE', C_RED = '#E0384D', C_BLUE = '#3AA8DC', C_AX = '#111';

/* ---------- state ---------- */
var figX = 0.45, figC = 1.1, figSide = 'free', figProj = false;
var figAnim = null, figAnimT = 0, figLast = 0;

/* ---------- helpers ---------- */
function pxAt(a, r) { return O.x + (r === undefined ? R : r) * Math.cos(a); }
function pyAt(a, r) { return O.y - (r === undefined ? R : r) * Math.sin(a); }
function arcPts(r, a0, a1) {
  var n = Math.max(3, Math.ceil(Math.abs(a1 - a0) * 34) + 3), out = [];
  for (var i = 0; i < n; i++) { var a = a0 + (a1 - a0) * i / (n - 1); out.push([pxAt(a, r), pyAt(a, r)]); }
  return out;
}
function dOf(pts, close) {
