  for (var i = 1; i < pts.length; i++) s += ' L' + pts[i][0].toFixed(2) + ',' + pts[i][1].toFixed(2);
  return close ? s + ' Z' : s;
}
function tri(g, x, y, dx, dy, size, color) {
