  var p = [[x, y], [x - dx * size + nx * hw, y - dy * size + ny * hw], [x - dx * size - nx * hw, y - dy * size - ny * hw]];
  return g.polygon(p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' ')).fill(color).stroke('none');
}
function svgText(group, parts, x, y, size, fill, anchor, halo) {
  var t = document.createElementNS(NSVG, 'text');
  t.setAttribute('x', x); t.setAttribute('y', y);
  t.setAttribute('font-family', 'Georgia, "Times New Roman", serif');
  t.setAttribute('font-size', size); t.setAttribute('fill', fill);
  t.setAttribute('text-anchor', anchor || 'start');
  if (halo) {
    t.setAttribute('paint-order', 'stroke'); t.setAttribute('stroke', '#fff');
    t.setAttribute('stroke-width', halo); t.setAttribute('stroke-linejoin', 'round');
  }
  for (var i = 0; i < parts.length; i++) {
    var ts = document.createElementNS(NSVG, 'tspan');
    ts.textContent = parts[i][0];
    if (parts[i][1]) ts.setAttribute('font-style', 'italic');
    t.appendChild(ts);
