}
function hov(el, txt, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(typeof txt === 'function' ? txt() : txt, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, typeof body === 'function' ? body() : body); });
  return el;
}

/* ---------- layer groups ---------- */
var gSector = figDraw.group();
var gStatic = figDraw.group();
var gProj = figDraw.group();
var gGeom = figDraw.group();
var gArcs = figDraw.group();
var gLabels = figDraw.group();
var gCap = figDraw.group();
var gReadout = figDraw.group();

/* ---------- static: axes ---------- */
gStatic.line(78, 390, 654, 390).stroke({ color: C_AX, width: 2.2 });
tri(gStatic, 668, 390, 1, 0, 15, C_AX);
gStatic.line(215, 708, 215, 28).stroke({ color: C_AX, width: 2.2 });
tri(gStatic, 215, 14, 0, -1, 15, C_AX);

/* ---------- static: unit circle (left part dashed) ---------- */
var arcSolid = gStatic.path(dOf(arcPts(R, -2.24, 2.24))).fill('none')
  .stroke({ color: C_CIRC, width: 5, linecap: 'round' });
gStatic.path(dOf(arcPts(R, 2.44, 2.87))).fill('none').stroke({ color: C_CIRC, width: 5, linecap: 'round' });
gStatic.path(dOf(arcPts(R, -2.87, -2.44))).fill('none').stroke({ color: C_CIRC, width: 5, linecap: 'round' });
hov(arcSolid, 'Unit circle: every angle θ gives the point (cos θ, sin θ)',
  'The unit circle', 'Each real number θ is wrapped onto the circle of radius 1, landing at the point (cos θ, sin θ). Moving θ a little moves that point only a little — this is exactly the geometric content of continuity of sine and cosine.');

/* ---------- sector ---------- */
var sectGrad = figDraw.gradient('linear', function (add) {
  add.stop(0, '#b487c8'); add.stop(0.55, '#d9bfe3'); add.stop(1, '#f8f1fb');
});
sectGrad.from(0.15, 0).to(0.65, 1);
var sectorPath = gSector.path('M0,0').fill(sectGrad).stroke({ color: '#a37cb8', width: 0.8, opacity: 0.45 });
hov(sectorPath, function () { return 'Angular gap |x − c| = ' + Math.abs(figX - figC).toFixed(3) + ' rad'; },
  'The angular gap', 'The shaded sector spans the angles between x and c. Its width is |x − c| — the quantity we are letting go to zero. As the sector closes, P slides along the arc onto Q.');

/* ---------- radii and dots ---------- */
var radiusQ = gGeom.line(O.x, O.y, O.x, O.y).stroke({ color: '#222', width: 1.8 });
var radiusP = gGeom.line(O.x, O.y, O.x, O.y).stroke({ color: C_RED, width: 2.4 });
var dotQ = gGeom.circle(15).fill(C_BLUE).stroke({ color: '#fff', width: 1.5 });
var dotP = gGeom.circle(15).fill(C_RED).stroke({ color: '#fff', width: 1.5 });
var hitQ = gGeom.circle(34).fill('#fff').opacity(0);
var hitP = gGeom.circle(34).fill('#fff').opacity(0);
hov(hitQ, function () { return 'Q = (cos c, sin c) = (' + Math.cos(figC).toFixed(3) + ', ' + Math.sin(figC).toFixed(3) + ')'; },
  'Q — the target value', 'Q is fixed at the angle c, with coordinates exactly (cos c, sin c). These are the function VALUES at c. A limit statement asks whether P’s coordinates can be forced as close to these numbers as we like.');
hov(hitP, function () { return 'P = (cos x, sin x) = (' + Math.cos(figX).toFixed(3) + ', ' + Math.sin(figX).toFixed(3) + ')'; },
  'P — the moving point', 'P sits at the angle x. Its horizontal coordinate is cos x and its vertical coordinate is sin x. Drag the x slider: as x → c the point P → Q, so cos x → cos c and sin x → sin c.');

/* ---------- caption box ---------- */
gCap.rect(500, 96).move(100, 750).fill('#fff').stroke({ color: '#b5b5b5', width: 2 });
svgText(gCap, [['As ', 0], ['x', 1], [' approaches ', 0], ['c', 1], [' the point', 0]], 130, 792, 24, '#1a1a1a', 'start');
svgText(gCap, [['P', 1], [' approaches the point ', 0], ['Q', 1], ['.', 0]], 130, 826, 24, '#1a1a1a', 'start');
var capHit = gCap.rect(500, 96).move(100, 750).fill('#fff').opacity(0);
hov(capHit, 'Click for the key idea', 'Why sine and cosine are continuous',
  'Because the point on the unit circle moves continuously with the angle, closing the gap in angle automatically closes the gap in BOTH coordinates. Hence lim(x→c) cos x = cos c and lim(x→c) sin x = sin c, for every real number c.');

/* ---------- readout ---------- */
gReadout.rect(190, 98).move(14, 12).radius(4).fill('#fff').opacity(0.9).stroke({ color: '#dfe3e6', width: 1 });
var rd = [];
for (var ri = 0; ri < 4; ri++) {
  rd.push(gReadout.text('').font({ family: 'sans-serif', size: 13, anchor: 'start' }).fill('#333').move(24, 18 + ri * 22));
}

/* ---------- dynamic render ---------- */
function drawProjections() {
  gProj.clear();
  if (!figProj) return;
  var px = pxAt(figX), py = pyAt(figX), qx = pxAt(figC), qy = pyAt(figC);
  function guides(x, y, col, w) {
    gProj.line(x, y, x, O.y).stroke({ color: col, width: w, dasharray: '5,4' });
    gProj.line(x, y, O.x, y).stroke({ color: col, width: w, dasharray: '5,4' });
    gProj.circle(6).center(x, O.y).fill(col);
    gProj.circle(6).center(O.x, y).fill(col);
  }
  guides(qx, qy, '#7cc4e6', 1.5);
  guides(px, py, '#e79aa5', 1.5);
  var cosYp = (py < O.y) ? O.y + 24 : O.y - 14;
  var cosYq = (Math.abs(px - qx) < 52 && ((py < O.y) === (qy < O.y))) ? cosYp + 22 : ((qy < O.y) ? O.y + 24 : O.y - 14);
  svgText(gProj, [['cos ', 0], ['c', 1]], qx, cosYq, 17, '#2F8FBF', 'middle', 3.5);
  svgText(gProj, [['cos ', 0], ['x', 1]], px, cosYp, 17, '#C43A4C', 'middle', 3.5);
  var sinYq = qy + 6, sinYp = py + 6;
  if (Math.abs(sinYp - sinYq) < 20) sinYq = sinYp + 22;
  svgText(gProj, [['sin ', 0], ['c', 1]], O.x - 12, sinYq, 17, '#2F8FBF', 'end', 3.5);
  svgText(gProj, [['sin ', 0], ['x', 1]], O.x - 12, sinYp, 17, '#C43A4C', 'end', 3.5);
}

function figRender() {
  var a = figX, c = figC, gap = Math.abs(a - c);
  var px = pxAt(a), py = pyAt(a), qx = pxAt(c), qy = pyAt(c);

  /* sector */
  var a0 = Math.min(a, c), a1 = Math.max(a, c);
  sectorPath.plot(dOf([[O.x, O.y]].concat(arcPts(R, a0, a1)), true));
  sectorPath.opacity(gap < 0.005 ? 0 : 1);

  radiusQ.plot(O.x, O.y, qx, qy);
  radiusP.plot(O.x, O.y, px, py);
  dotQ.center(qx, qy); dotP.center(px, py);
  hitQ.center(qx, qy); hitP.center(px, py);

  /* angle arcs + curved motion arrow */
  gArcs.clear();
  var rX = 60, rC = 98;
  if (Math.abs(c) > 0.06) {
    gArcs.path(dOf(arcPts(rC, 0, c))).fill('none').stroke({ color: '#222', width: 1.4 });
    var sc = c >= 0 ? 1 : -1;
    tri(gArcs, pxAt(c, rC), pyAt(c, rC), -Math.sin(c) * sc, -Math.cos(c) * sc, 10, '#222');
  }
  if (Math.abs(a) > 0.06) {
    gArcs.path(dOf(arcPts(rX, 0, a))).fill('none').stroke({ color: '#222', width: 1.4 });
    var sa = a >= 0 ? 1 : -1;
    tri(gArcs, pxAt(a, rX), pyAt(a, rX), -Math.sin(a) * sa, -Math.cos(a) * sa, 10, '#222');
  }
  if (gap > 0.16) {
    var dir = (c > a) ? 1 : -1;
    var aa0 = a + 0.17 * dir, aa1 = a + 0.80 * (c - a), aam = a + 0.49 * (c - a);
    var sx = pxAt(aa0, R + 26), sy = pyAt(aa0, R + 26);
    var ex = pxAt(aa1, R + 52), ey = pyAt(aa1, R + 52);
    var cx = pxAt(aam, R + 66), cy = pyAt(aam, R + 66);
    gArcs.path('M' + sx.toFixed(1) + ',' + sy.toFixed(1) + ' Q' + cx.toFixed(1) + ',' + cy.toFixed(1) +
      ' ' + ex.toFixed(1) + ',' + ey.toFixed(1)).fill('none').stroke({ color: '#111', width: 2.2, linecap: 'round' });
    tri(gArcs, ex, ey, ex - cx, ey - cy, 14, '#111');
  }

  /* labels */
  gLabels.clear();
  svgText(gLabels, [['c', 1]], pxAt(c / 2, rC + 22), pyAt(c / 2, rC + 22) + 7, 23, '#111', 'middle', 3.5);
  svgText(gLabels, [['x', 1]], pxAt(a / 2, rX + 20), pyAt(a / 2, rX + 20) + 7, 23, '#111', 'middle', 3.5);

  /* Q label (radially outside) */
  var qlx = pxAt(c, R + 46), qly = pyAt(c, R + 46) - 6;
  var qAnch = Math.cos(c) >= -0.15 ? 'start' : 'end';
  if (qAnch === 'start' && qlx + 210 > 670) qlx = 670 - 210;
  if (qAnch === 'end' && qlx - 210 < 10) qlx = 220;
  qly = Math.max(40, Math.min(700, qly));
  svgText(gLabels, [['Q', 1], ['(cos ', 0], ['c', 1], [', sin ', 0], ['c', 1], [')', 0]], qlx, qly, 23, '#111', qAnch, 4);

  /* P label (rotated away from Q when they are close, with leader line) */
  var rot = 0.36 * Math.max(0, (0.55 - gap) / 0.55);
  var aL = a + (a > c ? rot : -rot);
  var plx = pxAt(aL, R + 28), ply = pyAt(aL, R + 28) + 7;
  var pAnch = Math.cos(aL) >= -0.15 ? 'start' : 'end';
  if (pAnch === 'start' && plx + 200 > 672) plx = 672 - 200;
  if (pAnch === 'end' && plx - 200 < 8) plx = 208;
  ply = Math.max(40, Math.min(704, ply));
  if (rot > 0.05) {
    gLabels.line(px, py, pxAt(aL, R + 16), pyAt(aL, R + 16)).stroke({ color: '#b0b0b0', width: 1 });
  }
  svgText(gLabels, [['P', 1], ['(cos ', 0], ['x', 1], [', sin ', 0], ['x', 1], [')', 0]], plx, ply, 23, '#111', pAnch, 4);

  drawProjections();

  /* readout */
  var dc = Math.abs(Math.cos(a) - Math.cos(c)), ds = Math.abs(Math.sin(a) - Math.sin(c));
  rd[0].text('x = ' + a.toFixed(3) + '    c = ' + c.toFixed(3));
  rd[1].text('|x − c| = ' + gap.toFixed(3));
  rd[2].text('|cos x − cos c| = ' + dc.toFixed(3));
  rd[3].text('|sin x − sin c| = ' + ds.toFixed(3));
  rd[1].fill(gap < 0.02 ? '#1a8a3a' : '#333');
  rd[2].fill(dc < 0.02 ? '#1a8a3a' : '#333');
  rd[3].fill(ds < 0.02 ? '#1a8a3a' : '#333');
}

/* ---------- controls ---------- */
function setSlider(id, v) {
  var el = document.getElementById(id + 'Input'); if (el) el.value = v;
  var o = document.getElementById(id + 'Val'); if (o) o.value = (+v).toFixed(2);
}
function syncSliders() { setSlider('angleX', figX); setSlider('targetC', figC); }
function figClampX(v) {
  v = Math.max(-1.2, Math.min(2.8, v));
  if (figSide === 'below') v = Math.min(v, Math.max(-1.2, figC - 0.02));
  if (figSide === 'above') v = Math.max(v, Math.min(2.8, figC + 0.02));
  return v;
}
function update_angleX(v) { stopAnim(); figX = figClampX(v); syncSliders(); figRender(); }
function update_targetC(v) { stopAnim(); figC = v; figX = figClampX(figX); syncSliders(); figRender(); }
function set_approachSide(v) { figSide = v; figX = figClampX(figX); syncSliders(); figRender(); }
function toggle_showProjections(on) { figProj = on; figRender(); }

function stopAnim() {
  if (figAnim) { cancelAnimationFrame(figAnim); figAnim = null; }
  var b = document.getElementById('playBtn');
  if (b) { b.textContent = '▶ Animate x → c from both sides'; b.classList.remove('active'); }
}
function trigger_playApproach() {
  if (figAnim) { stopAnim(); return; }
  figAnimT = 0; figLast = performance.now();
  var b = document.getElementById('playBtn');
  b.textContent = '⏸ Pause animation'; b.classList.add('active');
  function frame(t) {
    var dt = Math.min(0.05, (t - figLast) / 1000); figLast = t;
    figAnimT += dt * 0.5; if (figAnimT >= 2) figAnimT -= 2;
    var amp = Math.min(0.85, Math.max(0.12, Math.min(figC + 1.2, 2.8 - figC)));
    var u, sgn;
    if (figSide === 'below') { u = figAnimT % 1; sgn = -1; }
    else if (figSide === 'above') { u = figAnimT % 1; sgn = 1; }
    else if (figAnimT < 1) { u = figAnimT; sgn = -1; }
    else { u = figAnimT - 1; sgn = 1; }
    var e = (1 - u) * (1 - u);
    figX = Math.max(-1.2, Math.min(2.8, figC + sgn * amp * e));
    syncSliders(); figRender();
    figAnim = requestAnimationFrame(frame);
  }
  figAnim = requestAnimationFrame(frame);
}

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'The fixed target Q', narration: 'A point Q sits on the unit circle at the fixed angle c; its coordinates are exactly (cos c, sin c). This is the value we want the function to approach.', state: { targetC: 1.1, angleX: 1.1, showProjections: false, approachSide: 'free' } },
  { title: 'Pull P away from Q', narration: 'Move the angle x away from c. The red point P separates from Q and a shaded sector opens up between the two radii — the sector\'s size measures how far apart the angles are.', state: { angleX: 0.3, targetC: 1.1, approachSide: 'free' } },
  { title: 'Coordinates are the projections', narration: 'Drop P onto the axes: its shadow on the x-axis is cos x and on the y-axis is sin x. Q\'s shadows are cos c and sin c. The limit question is whether the shadows meet when the points meet.', state: { angleX: 0.5, targetC: 1.1, showProjections: true } },
  { title: 'Approach from below', narration: 'Slide x upward toward c. The sector narrows, P slides along the arc, and cos x and sin x creep toward cos c and sin c.', state: { approachSide: 'below', angleX: 1.02, targetC: 1.1, showProjections: true } },
  { title: 'Approach from above', narration: 'Now come in from the other side, x greater than c. P arrives at exactly the same place — the one-sided limits agree.', state: { approachSide: 'above', angleX: 1.18, targetC: 1.1, showProjections: true } },
  { title: 'Continuity at every c', narration: 'Move Q anywhere on the circle and repeat: no matter where c is, P can be brought arbitrarily close to Q. Hence sin and cos are continuous at every real number.', state: { targetC: 2.3, angleX: 2.3, approachSide: 'free', showProjections: true } }
];
var stepIndex = 0;
function normSide(s) {
  if (!s) return 'free';
  if (s.indexOf('below') >= 0) return 'below';
  if (s.indexOf('above') >= 0) return 'above';
  return 'free';
}
function applyState(s) {
  stopAnim();
  if (s.approachSide !== undefined) {
    figSide = normSide(s.approachSide);
    document.getElementById('approachSideInput').value = figSide;
  }
  if (s.showProjections !== undefined) {
    figProj = !!s.showProjections;
    document.getElementById('showProjectionsInput').checked = figProj;
  }
  if (s.targetC !== undefined) figC = s.targetC;
  if (s.angleX !== undefined) figX = s.angleX;
  syncSliders(); figRender();
}
function showStepText() {
  document.getElementById('demoNarration').textContent = STEPS[stepIndex].title + ' — ' + STEPS[stepIndex].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIndex + 1) + '/' + STEPS.length;
}
function goStep(i) {
  stepIndex = (i + STEPS.length) % STEPS.length;
  applyState(STEPS[stepIndex].state);
  showStepText();
}
function nextStep() { goStep(stepIndex + 1); }
function prevStep() { goStep(stepIndex - 1); }

/* ---------- init (default view = faithful reconstruction) ---------- */
syncSliders();
figRender();
showStepText();
window.__markRendered();
